import { useEffect } from 'react';

import { CarouselProps } from '../types';

/**
 * Custom hook that handles the autoplay of the carousel.
 */
export function useAutoplay(
  { autoplay, autoplayInterval }: CarouselProps,
  goToSlide: (directionalSlideIndex) => void,
  currentSlideIndex: number,
) {
  const shouldAutoplay = autoplay;

  useEffect(() => {
    if (!shouldAutoplay) return;
    const interval = 5000; // default
    const isInterval = typeof autoplayInterval === 'number' && autoplayInterval > 0;
    const timeout = setTimeout(() => {
      goToSlide(currentSlideIndex + 1);
    }, isInterval ? autoplayInterval : interval);

    return () => clearTimeout(timeout);
  }, [shouldAutoplay, autoplayInterval, currentSlideIndex, goToSlide]);
}
```

