            <SvgIcon component={WorkspacesIcon} />
          </NotebookButton>
          <NewWorkspaceDialog
            datasetUUIDs={new Set([uuid])}
            control={control}
            errors={errors}
            {...rest}
          />
        </>
      )}
    </>
  );
}

