import { useCallback } from 'react';

import { useFlaskDataContext } from 'js/components/Contexts';
import { trackEvent } from 'js/helpers/trackers';

type TrackEntityPageEventOptions = {
  action: string;
};

export default function useTrackEntityPageEvent() {
  const { entity = {} } = useFlaskDataContext();
  const { hubmap_id: label, entity_type } = entity;

  const category = entity_type ? `${entity_type} Page` : 'Detail Page';

  const trackEntityPageEvent = useCallback(
    ({ action }: TrackEntityPageEventOptions) => {
      trackEvent({
        category,
        action,
        label,
      });
    },
    [category, label],
  );

  return trackEntityPageEvent;
}

